from cryptography.hazmat.primitives.ciphers.aead import AESGCM


class Solver:
    """Encrypt inputs directly with the platform's optimized AES-GCM backend."""

    def solve(self, problem, **kwargs):
        encrypted = AESGCM(problem["key"]).encrypt(
            problem["nonce"],
            problem["plaintext"],
            problem["associated_data"],
        )
        return {
            "ciphertext": encrypted[:-16],
            "tag": encrypted[-16:],
        }

